#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998;
    long long inv[200005];
    long long fact[200005];
    long long invFact[200005];

    Mod998() {
        precompute();
    }

    void precompute() {
        fact[0] = 1;
        for (int i = 1; i < 200005; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        inv[200004] = modInverse(fact[200004], MOD);
        for (int i = 200003; i >= 0; i--) {
            inv[i] = (inv[i + 1] * (i + 1)) % MOD;
        }
        invFact[0] = 1;
        for (int i = 1; i < 200005; i++) {
            invFact[i] = (invFact[i - 1] * i) % MOD;
        }
    }

    long long modInverse(long long a, long long m) {
        long long m0 = m, t, q;
        long long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m, a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long div(long long a, long long b) {
        return mult(a, modInverse(b, MOD));
    }

    long long ncr(int n, int r) {
        if (r > n || r < 0) return 0;
        return mult(fact[n], mult(invFact[r], invFact[n - r]));
    }

    long long paritySign(int x) {
        return (x % 2 == 0) ? 1 : -1;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalCards, totalShuffles;
    cin >> totalCards >> totalShuffles;
    Mod998 mod;

    long long total = totalCards + totalShuffles;
    long long invTotal = mod.modInverse(total, mod.MOD);
    vector<long long> p(totalCards + 2, 0);
    p[0] = 1;
    long long phaseSize = 1;

    for (int i = 0; i < totalCards; i++) {
        long long numerator = p[i];
        long long denominator = total - i;
        long long invDenominator = mod.modInverse(denominator, mod.MOD);
        p[i + 1] = mod.mult(numerator, invDenominator);
        phaseSize = mod.add(phaseSize, p[i + 1]);
    }

    long long result = 0;
    for (int k = 1; k <= totalCards; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = (totalShuffles + k + k - 1) / k; // ceil division
        long long term = mod.mult(sign, mod.ncr(totalCards, k));
        term = mod.mult(term, numPhases);
        term = mod.mult(term, phaseSize);
        result = mod.add(result, term);
    }

    cout << result << "\n";

    return 0;
}

